  || canonicalHash(marker.materialHash || marker.material_hash) !== canonicalMaterialHash
  || markerMaterialHashVersion !== materialHashVersion || markerPlanHash !== planHash
  || markerPresetRowVersion !== presetRowVersion || markerPublicationMode !== publicationMode) {
  fail('OZON_INTAKE_VERIFY_MARKER_SNAPSHOT_MISMATCH', 'marker 必须包含与 claim 相同的店铺、策略、素材、计划、预设版本及发布模式冻结快照');
}
const markerProductPath = path.join(path.dirname(markerPath), 'product.json');
if (!fs.existsSync(markerProductPath)) fail('OZON_INTAKE_VERIFY_PRODUCT_MISSING', '验票目录缺少 product.json');
const productInfo = fs.lstatSync(markerProductPath);
if (productInfo.isSymbolicLink() || !productInfo.isFile()) fail('OZON_INTAKE_VERIFY_PRODUCT_INVALID', 'product.json 必须是普通文件');
const productContentHash = crypto.createHash('sha256').update(fs.readFileSync(markerProductPath)).digest('hex');
if (normalizeHash(marker.productContentHash || marker.product_content_hash) !== productContentHash) {
  fail('OZON_INTAKE_PRODUCT_CONTENT_HASH_MISMATCH', 'product.json exact bytes 与 marker.productContentHash 不一致');
}
