  fail('OZON_INTAKE_MATERIALIZATION_HASH_MISMATCH', 'marker.materializationHash 与 publication materialization 合同不一致');
}
const ticket = String(marker.ticket || marker.intakeTicket || marker.intake_ticket || marker.verificationTicket || marker.verification_ticket || '').trim();
if (!/^hmac-sha256:[a-f0-9]{64}$/.test(ticket)) fail('OZON_INTAKE_TICKET_INVALID', '新 intake 缺少后端签发的 hmac-sha256 ticket');
const canonicalProductContentHash = canonicalHash(productContentHash);
const canonicalMaterializationHash = canonicalHash(input.materializationHash);
const canonicalOfferContractHash = canonicalHash(input.offerContractHash);
if (!canonicalProductContentHash || !canonicalMaterializationHash || !canonicalOfferContractHash) {
  fail('OZON_INTAKE_VERIFY_HASH_INVALID', '后端 intake verify 的三个 hash 必须可规范化为 sha256:<64hex>');
}
return [{ json: {
  requiresBackendVerification: true,
  verificationRequest: {
    jobId,
    taskId,
    storeId,
    storeAlias,
    publicationId,
    credentialVersionId: credentialVersionId || null,
    credentialBindingMode,
    storeConfigVersion,
    warehouseId,
    sku,
    revision,
    productContentHash: canonicalProductContentHash,
    materializationHash: canonicalMaterializationHash,
    contentPolicyVersion,
    materialHash: canonicalMaterialHash,
    materialHashVersion,
    planHash,
    presetRowVersion,
    publicationMode,
    offerContractHash: canonicalOfferContractHash,
    ticket,
    rowVersion,
    leaseToken
  }
} }];

const response = $input.first().json || {};
const statusCode = Number(response.statusCode || response.status || 0);
const body = response.body && typeof response.body === 'object' ? response.body : response;
if (statusCode < 200 || statusCode >= 300 || body.verified !== true) {
  const error = new Error('OZON_INTAKE_BACKEND_VERIFY_FAILED: 后端 intake 票据验证未返回 2xx verified');
  error.code = 'OZON_INTAKE_BACKEND_VERIFY_FAILED';
  throw error;
}
return [{ json: { intakeVerified: true, verificationId: String(body.verificationId || body.receiptId || '') } }];
